// ───────────────────────── общие: прокрутка вниз-вверх ─────────────────────────

/** Свайп вниз (контент уезжает вниз → видна верхняя часть). Только середина экрана (правило 14.10). */
export async function swipeDown() {
  const { width, height } = await driver.getWindowSize();
  await driver.action('pointer', { parameters: { pointerType: 'touch' } })
    .move({ x: Math.round(width / 2), y: Math.round(height * 0.3) })
    .down().pause(80)
    .move({ duration: 400, x: Math.round(width / 2), y: Math.round(height * 0.75) })
    .up().perform();
}
/** Главная, прокрутка в самый верх. */
export async function homeTop() {
  await toHome();
  for (let i = 0; i < 8; i++) await swipeDown();
}

/** Тексты всех видимых TextView/StaticText (Android — только видимые, поэтому прокручиваем) за проходы сверху вниз. */
export async function collectNodes(passes = 6): Promise<UiNode[]> {
  const seen = new Map<string, UiNode>();
  for (let p = 0; p < passes; p++) {
    let added = 0;
    for (const n of await nodes()) {
      if (!n.visible || n.w <= 0 || n.h <= 0) continue;
      const k = `${n.label}|${n.x}`;
      if (!seen.has(k)) { seen.set(k, n); added++; }
    }
    if (p > 0 && !added) break;
    await swipeUp();
  }
  return [...seen.values()];
}

// ───────────────────────── #536fbb: имя ближайшей молитвы на главной ─────────────────────────

export const PRAYER_NAMES = ['שחרית', 'מנחה', 'ערבית'];
/** Большая надпись имени молитвы на главной (верх экрана, TextView с точным именем). */
export async function homePrayerNode(): Promise<UiNode> {
  let found: UiNode | undefined;
  await driver.waitUntil(async () => {
    const { height } = await driver.getWindowSize();
    found = (await nodes())
      .filter((n) => PRAYER_NAMES.includes(n.label) && n.visible && n.w > 0 && n.h > 0 && n.y < height * 0.5 && /TextView/.test(n.type))
      .sort((a, b) => a.y - b.y)[0];
    return Boolean(found);
  }, { timeout: 25000, interval: 1000, timeoutMsg: 'на главной нет имени молитвы (שחרית / מנחה / ערבית)' });
  return found!;
}

// ───────────────────────── #86e6bc: «תאריכים חשובים» ─────────────────────────

export const IMPORTANT = 'תאריכים חשובים';
export const ADD_LABEL = 'הוספת תאריך חשוב';
export const SHOW_ALL = 'להראות הכל';
export const HIDE_ALL = 'להסתיר הכל';
export const EMPTY_TWO_WEEKS = 'אין תאריכים חשובים בשבועיים הקרובים.';
export const QA_PREFIX = 'QA-1911';
export const editLabel = (name: string) => `${name}: פתיחה לעריכה`;

/** ISO-дата (YYYY-MM-DD) через n дней от сегодня — по локальной дате компьютера (телефон на том же часовом поясе). */
export function isoPlus(n: number): string {
  const d = new Date();
  d.setDate(d.getDate() + n);
  const p = (x: number) => String(x).padStart(2, '0');
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;
}

/** «בית» → в верх → прокрутка до заголовка «תאריכים חשובים» (кнопка «+» теперь в его строке, а не внизу списка). */
export async function homeDatesHeading(): Promise<UiNode> {
  await homeTop();
  for (let i = 0; i < 10; i++) {
    const h = (await nodes()).find((n) => n.label === IMPORTANT && n.visible && /TextView|StaticText/.test(n.type));
    if (h) return h;
    await swipeUp();
  }
  throw new Error(`на главной не найден заголовок «${IMPORTANT}»`);
}

/** Кнопка переключателя «להראות הכל» / «להסתיר הכל»: по имени кнопки, иначе по тексту. */
export async function toggleBtn(name: string): Promise<El | null> {
  const b = await button(name);
  if (await b.isDisplayed().catch(() => false)) return b as unknown as El;
  const t = await byText(name);
  if (await t.isDisplayed().catch(() => false)) return t as unknown as El;
  return null;
}
/** Переключатель виден на экране, к которому прокручено сейчас. */
export async function toggleShown(name: string) {
  return (await toggleBtn(name)) !== null;
}
/** Прокрутить вниз, пока не появится переключатель (до max свайпов); null — нет. */
export async function findToggle(name: string, max = 10): Promise<El | null> {
  for (let i = 0; i < max; i++) {
    const t = await toggleBtn(name);
    if (t) return t;
    await swipeUp();
  }
  return null;
}

/** Свернуть список (если сейчас «להסתיר הכל» — нажать). Возвращает, был ли он развёрнут. */
export async function ensureCollapsed(): Promise<boolean> {
  await homeDatesHeading();
  const hide = await findToggle(HIDE_ALL, 10);
  if (!hide) return false;
  await hide.click();
  await driver.waitUntil(async () => !(await toggleShown(HIDE_ALL)), { timeout: 10000, timeoutMsg: 'после «להסתיר הכל» кнопка не сменилась' });
  return true;
}
/** Развернуть (нажать «להראות הכל»). false — кнопки нет. */
export async function expandAll(): Promise<boolean> {
  await homeDatesHeading();
  const show = await findToggle(SHOW_ALL, 10);
  if (!show) return false;
  await show.click();
  await driver.waitUntil(async () => (await findToggle(HIDE_ALL, 6)) !== null, { timeout: 10000, timeoutMsg: 'после «להראות הכל» нет «להסתיר הכל»' });
  return true;
}

/** Подписи всех карточек списка («<имя>: פתיחה לעריכה») при прокрутке главной сверху вниз; для Android — по проходам. */
export async function dateCardLabels(): Promise<string[]> {
  await homeDatesHeading();
  const all = await collectNodes(10);
  return [...new Set(all.map((n) => n.label).filter((l) => l.endsWith(': פתיחה לעריכה')))];
}

/** Карточка по имени: сколько свайпов от заголовка и y (для проверки порядка); null — не найдена за max свайпов. */
export async function findCard(name: string, max = 10): Promise<{ swipes: number; y: number } | null> {
  await homeDatesHeading();
  for (let i = 0; i <= max; i++) {
    const el = await byLabel(editLabel(name));
    if (await el.isDisplayed().catch(() => false)) {
      const { y } = await el.getLocation();
      return { swipes: i, y };
    }
    await swipeUp();
  }
  return null;
}
/** Порядок «a раньше b» сверху вниз (эвристика: сначала по числу свайпов до появления, при равенстве — по y). */
export const isBefore = (a: { swipes: number; y: number }, b: { swipes: number; y: number }) =>
  a.swipes < b.swipes || (a.swipes === b.swipes && a.y < b.y);

/** Выбрать день в календаре окна: ячейка label «YYYY-MM-DD, …»; если её нет — «החודש הבא» (до 2 раз). */
export async function pickDay(iso: string) {
  for (let i = 0; i < 3; i++) {
    const day = await byLabelStartsWith(`${iso}, `);
    if (await day.waitForDisplayed({ timeout: i === 0 ? 8000 : 5000 }).then(() => true, () => false)) { await day.click(); return; }
    await tapLabel('החודש הבא');
  }
  throw new Error(`в календаре нет дня ${iso}`);
}

/** Создать «תאריך חשוב» name на дату iso: «+» → «תאריך חשוב» → «שם התאריך» → день → «הוסף תאריך». */
export async function addImportantDate(name: string, iso: string) {
  await homeDatesHeading();
  await tapLabel(ADD_LABEL);
  await tapText('תאריך חשוב');
  const field = await dateNameField();
  await field.setValue(name);
  if (driver.isAndroid && (await driver.isKeyboardShown().catch(() => false))) await driver.hideKeyboard().catch(() => {});
  await pickDay(iso);
  await tapText('הוסף תאריך');
  await expect(byText('הוסף תאריך')).not.toBeDisplayed({ wait: 10000 });
}

/** Удалить ВСЕ записи «QA-1911-…» (в развёрнутом списке, иначе дальние скрыты): карандаш → «מחיקת התאריך» → «מחיקה». */
export async function deleteAllQa1911() {
  for (let guard = 0; guard < 8; guard++) {
    await homeDatesHeading();
    await findToggle(SHOW_ALL, 8).then((t) => t?.click());           // развернуть, если есть скрытые
    await homeDatesHeading();
    const sel = driver.isAndroid
      ? `android=new UiSelector().descriptionMatches(".*${QA_PREFIX}-.*: פתיחה לעריכה")`
      : `-ios predicate string:name MATCHES ".*${QA_PREFIX}-.*: פתיחה לעריכה"`;
    let target: El | null = null;
    for (let i = 0; i < 10 && !target; i++) {
      const list = await $$(sel).getElements();
      for (const el of list) if (await el.isDisplayed().catch(() => false)) { target = el; break; }
      if (!target) await swipeUp();
    }
    if (!target) return;
    await target.click();
    await (await byText('עריכת תאריך')).waitForDisplayed({ timeout: 15000 });
    const del = await byText('מחיקת התאריך');
    for (let i = 0; i < 4 && !(await del.isDisplayed().catch(() => false)); i++) await swipeUp();
    await del.click();
    const confirm = await byText('מחיקה');
    await confirm.waitForDisplayed({ timeout: 10000 });
    await confirm.click();
    await expect(byText('עריכת תאריך')).not.toBeDisplayed({ wait: 15000 });
  }
}

