// ───────────────────────── #1f0dd2: диапазон часов молитвы (RTL) ─────────────────────────

export type Range = { first: string; second: string; fMin: number; sMin: number };
const BIDI = /[‎‏‪-‮⁦-⁩]/g;
const RANGE_RE = /(\d{1,2}):(\d{2})\s*-\s*(\d{1,2}):(\d{2})/;
/** «HH:MM - HH:MM» из строки (без управляющих символов направления): первое время — в логическом порядке текста. */
export function parseRange(label: string): Range | null {
  const m = label.replace(BIDI, '').match(RANGE_RE);
  if (!m) return null;
  const f = `${m[1].padStart(2, '0')}:${m[2]}`, s = `${m[3].padStart(2, '0')}:${m[4]}`;
  return { first: f, second: s, fMin: +m[1] * 60 + +m[2], sMin: +m[3] * 60 + +m[4] };
}
/** Окно «не через полночь» (שחרית / מנחה): начало раньше конца. Для ערבית конец может быть «меньше» — не проверяем порядок. */
export const crossesMidnight = (r: Range) => r.sMin <= r.fMin;

/** Узел строки диапазона на главной (под еврейской датой, верх экрана): текст только «<время> - <время>». */
export async function homeRangeNode(): Promise<UiNode> {
  let found: UiNode | undefined;
  await driver.waitUntil(async () => {
    const { height } = await driver.getWindowSize();
    found = (await nodes())
      .filter((n) => n.visible && n.w > 0 && n.y < height * 0.5 && /^\s*[‎‏‪-‮⁦-⁩]*\d{1,2}:\d{2}\s*-\s*\d{1,2}:\d{2}\s*$/.test(n.label))
      .sort((a, b) => a.y - b.y)[0];
    return Boolean(found);
  }, { timeout: 25000, interval: 1000, timeoutMsg: 'на главной нет строки диапазона времени молитвы «ЧЧ:ММ - ЧЧ:ММ»' });
  return found!;
}

/** Отдельные узлы-времена «ЧЧ:ММ» внутри рамки узла диапазона (если дерево отдаёт цифры раздельно), слева направо. */
export async function timeNodesInside(box: UiNode): Promise<UiNode[]> {
  return (await nodes())
    .filter((n) => n.visible && n !== box && /^[‎‏]*\d{1,2}:\d{2}[‎‏]*$/.test(n.label)
      && n.x >= box.x - 2 && n.x + n.w <= box.x + box.w + 2 && n.y >= box.y - 2 && n.y + n.h <= box.y + box.h + 2)
    .sort((a, b) => a.x - b.x);
}

/** Шапка вкладки «המסע שלי»: «<молитва> <начало> - <конец>». */
export async function journeyHeader(): Promise<{ name: string; range: Range; node: UiNode }> {
  let hit: { name: string; range: Range; node: UiNode } | undefined;
  await driver.waitUntil(async () => {
    for (const n of await nodes()) {
      if (!n.visible) continue;
      const clean = n.label.replace(BIDI, '');
      const name = PRAYER_NAMES.find((p) => clean.includes(p));
      const range = parseRange(clean);
      if (name && range && clean.indexOf(name) < clean.search(RANGE_RE)) { hit = { name, range, node: n }; return true; }
    }
    return false;
  }, { timeout: 25000, interval: 1000, timeoutMsg: 'в шапке «המסע שלי» нет строки «<молитва> ЧЧ:ММ - ЧЧ:ММ»' });
  return hit!;
}
